-- River Run V1 PM Fall Chinook gauge baselines.
-- Source: USGS daily values, site 04122500, flow_cfs, 2019-01-01 through 2025-12-31.
-- Baseline version must match river-run endpoint CONFIG_VERSION: 2026-07-08.
-- Idempotent upsert only; does not alter public audit visibility, policies, snapshots, or refreshes.

on conflict (river_id, metric, day_of_year, baseline_version) do update set
  percentiles = excluded.percentiles,
  band_data = excluded.band_data,
  sample_count = excluded.sample_count,
  distinct_years = excluded.distinct_years,
  window_days = excluded.window_days,
  source_notes = excluded.source_notes;
